// Writes public/_redirects from src/lib/legacy-redirects.ts so the redirect map has one source of truth.
import { writeFileSync } from 'node:fs';
import { LEGACY_MOVES } from '../src/lib/legacy-redirects.ts';

const ARTICLES = LEGACY_MOVES.find(([from]) => from === '/artikel')[1];

const fixed = [
  `/blog ${ARTICLES} 301`,
  `/blog/* ${ARTICLES}/:splat 301`,
  '/kawal / 301',
  '/sitemap-index.xml /sitemap.xml 301',
  '/sitemap-0.xml /sitemap.xml 301',
];
const moves = LEGACY_MOVES.flatMap(([from, to]) => [`${from} ${to} 301`, `${from}/* ${to}/:splat 301`]);

const body = [
  '# Generated by scripts/make-redirects.mjs from src/lib/legacy-redirects.ts. Do not edit by hand.',
  ...fixed,
  '# BEGIN legacy',
  ...moves,
  '# END legacy',
  '',
].join('\n');

writeFileSync(new URL('../public/_redirects', import.meta.url), body);
console.log(`redirects: ${fixed.length + moves.length} rules`);
